import json
import requests
import os
from datetime import datetime
def task_func(json_data, unknown_key, save_dir=None):
    if not json_data or not unknown_key:
        raise ValueError("JSON data and unknown key must be non-empty strings.")

    try:
        data = json.loads(json_data)
        url = data[unknown_key]
    except (json.JSONDecodeError, KeyError) as e:
        raise ValueError(f"Error parsing JSON or extracting URL: {e}")

    if not isinstance(url, str) or not url.startswith(('http://', 'https://')):
        raise ValueError("Invalid URL extracted from JSON.")

    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise ValueError(f"Error downloading the file: {e}")

    timestamp = datetime.now().strftime('%Y%m%d%H%M%S%f')
    filename = f"{unknown_key}_{timestamp}.txt"
    if save_dir:
        filepath = os.path.join(os.path.abspath(save_dir), filename)
    else:
        filepath = os.path.abspath(filename)

    with open(filepath, 'wb') as f:
        f.write(response.content)

    return filepath

